import numpy as np


def r(x):
    # Maps x in [0, 1] to sin(pi * x / 2), which is strictly greater than x
    # for x in (0, 1), shifting the input towards the asymptotic regime of 1.
    return float(np.sin(np.pi * float(x) / 2))


def R(y_orig, y_new):
    # The output probability should increase or remain equal (modulo small numerical precision)
    return y_new >= y_orig - 1e-9
